window.DICTIONARY_ENTRY_SHARDS["0078-0061"]={"0078-0061:440ba5d3a0b7f4":{"word":"Xanten","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Xan·ten","de-DE":"Xan·ten"},"forms":[{"form":"Xantens","tags":["Genitiv","Singular"]},{"form":"des Xanten","tags":["Genitiv","Singular"]},{"form":"des Xantens","tags":["Genitiv","Singular"]},{"form":"(das) Xanten","tags":["Nominativ","Singular"]},{"form":"(dem) Xanten","tags":["Dativ","Singular"]}],"senses":[{"definition":"deutsche Stadt im Niederrheinischen Tiefland"}],"synonyms":["Castra Vetera","Xantum"],"origins":["über Xanctum von lateinisch: „ad Sanctōs“ = „bei den Heiligen“"],"examples":[{"text":"Xanten liegt am Niederrhein.","reference":""},{"text":"\"Die Überlebenden der Völkerwanderungsstürme übersiedelten auf den nahen Domhügel des heutigen Xantens. Jahrhundertelang dienten die\" Ruinen des antiken Colonia Ulpia Traiana \"der mittelalterlichen Stadt als Steinbruch.\"","reference":"Dieter Bartetzko: Hinein ins Leben der Antike. Im niederrheinischen Xanten hat das Römermuseum eröffnet. In: Frankfurter Allgemeine. Zeitung für Deutschland. Nummer 203, 30. August 2008, ISSN 0174-4909, Seite 33 (Feuilleton) ."}],"idioms":[],"collocations":[],"derivations":["Xantener","Xantenerin"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Xanten","id":"440ba5d3a0b7f4"},"0078-0061:51b85e1a06b27a":{"word":"Xanthippe","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Xan·thip·pe","de-DE":"Xan·thip·pe"},"forms":[{"form":"Xanthippe","tags":["Nominativ","Singular"]},{"form":"Xanthippen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Bezeichnung für eine zänkische Frau oder Ehefrau nach der Ehefrau von Sokrates"}],"synonyms":["Besen","boshaftes Weibsstück","Drachen","feuerspeiender Drache","Furie","Gewitterziege","Giftnudel","Hausdrachen","Hippe","Kratzbürste","Krähe","Meckertante","Meckerziege","Megäre","Schlange","Zicke","Zimtzicke","Zippe","zänkisches Weib"],"origins":["von dem griechischen Ξανθίππη (Xanthippē^☆) ^(→ grc) entlehnt und seit dem 16. Jahrhundert als Gattungsname im Deutschen belegt"],"examples":[{"text":"Du traust dich wohl nicht nach Hause zu deiner Xanthippe?","reference":""},{"text":"„Vors Fenster wird er ihn hängen, wie er die Möbel seiner ersten Frau, dieser Xanthippe, vors Fenster gehängt hat: den Nachtstuhl, den Schrank, die Kommode, alles hinaus vors Fenster, an langen Stricken.“","reference":"Hugo Ball: Flametti oder vom Dandysmus der Armen. Aufbau, Berlin/Weimar 1989, ISBN 3-351-01401-5 , Zitat Seite 46. Erstveröffentlichung 1918."},{"text":"„Seine Frau ist ’ne Xanthippe und imstande, ihm das Leben zur Hölle zu machen.“","reference":"Hans Fallada: Jeder stirbt für sich allein. 7. Auflage. Roman. Aufbau, Berlin 2013, ISBN 978-3-7466-2811-0, Seite 28. Ausgabe nach der Originalfassung des Autors von 1947."},{"text":"„Die Frau des Sokrates hieß Xanthippe und war gar keine.“","reference":"Frankfurter Allgemeine Zeitung, 28.06.1999, Nr. 146 / Seite 55, online"},{"text":"„Der komische Effekt der Szene entsteht aus dem Gegensatz zwischen den hehren Zielen, die Benjamin mit seiner Reise zu verfolgen vorgibt, und dem niedrigen Beweggrund des geschundenen Ehemannes, der den Klauen seiner Xanthippe entkommen soll.“","reference":"Jakob Hessing: Der jiddische Witz. Eine vergnügliche Geschichte. Beck, München 2020, ISBN 978-3-406-75473-9, Seite 63."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Xanthippe","id":"51b85e1a06b27a"},"0078-0061:b40f67dc120449":{"word":"Xanthippe","partOfSpeech":"Vorname","gender":"die","hyphenation":{"de-CH":"Xan·thip·pe","de-DE":"Xan·thip·pe"},"forms":[{"form":"X.","tags":["Kurzform"]},{"form":"Xanthippe","tags":["Nominativ","Singular"]},{"form":"Xanthippen","tags":["Nominativ","Plural"]},{"form":"Xanthippes","tags":["Nominativ","Plural"]},{"form":"Xanthippos","tags":["masculine"]}],"senses":[{"definition":"weiblicher Vorname"}],"synonyms":["Besen","boshaftes Weibsstück","Drachen","feuerspeiender Drache","Furie","Gewitterziege","Giftnudel","Hausdrachen","Hippe","Kratzbürste","Krähe","Meckertante","Meckerziege","Megäre","Schlange","Zicke","Zimtzicke","Zippe","zänkisches Weib"],"origins":["Xanthippe (Ξανθίππη (Xanthippē^☆) ^(→ grc)) setzt sich aus den altgriechischen Wörtern ξανθός (xanthos^☆) ^(→ grc) (gelblich, blond) und ἵππος (hippos^☆) ^(→ grc) (Pferd, Ross) zusammen.."],"examples":[{"text":"Xanthippe hat rote Haare.","reference":""},{"text":"Ich kenne niemanden, der Xanthippe heißt.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Xanthippe","id":"b40f67dc120449"},"0078-0061:328c3224a61b58":{"word":"Xander","partOfSpeech":"Vorname","gender":"der","hyphenation":{"de-CH":"Xan·der","de-DE":"Xan·der"},"forms":[{"form":"Xander","tags":["Nominativ","Singular"]},{"form":"Xandra","tags":["feminine"]},{"form":"Xanders","tags":["Nominativ","Plural"]}],"senses":[{"definition":"männlicher Vorname, Kurzform von Alexander"}],"synonyms":[],"origins":["[1] Aus dem Rätoromanischen"],"examples":[{"text":"Xander Mustermann ist ein schöner Junge.","reference":""},{"text":"Xander ist 20 Jahre alt.","reference":""},{"text":"Grüß bitte Xander Mustermann herzlich von mir.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xander","id":"328c3224a61b58"},"0078-0061:d0c289d03c838b":{"word":"Xander","partOfSpeech":"Nachname","gender":"die","hyphenation":{"de-CH":"Xan·der","de-DE":"Xan·der"},"forms":[{"form":"Sander","tags":["variant"]},{"form":"Xander","tags":["Nominativ","Singular","masculine"]},{"form":"Xandry","tags":["variant"]},{"form":"Zander","tags":["variant"]},{"form":"Sanders","tags":["variant"]},{"form":"Xanders","tags":["variant"]},{"form":"Zanders","tags":["variant"]},{"form":"dem Xander","tags":["Dativ","Singular","masculine"]},{"form":"den Xander","tags":["Dativ","Plural"]},{"form":"der Xander","tags":["Nominativ","Singular","masculine"]},{"form":"des Xander","tags":["Genitiv","Singular","masculine"]},{"form":"die Xander","tags":["Nominativ","Singular","feminine"]},{"form":"den Xanders","tags":["Dativ","Plural"]},{"form":"der Xanders","tags":["Genitiv","Plural"]},{"form":"des Xanders","tags":["Genitiv","Singular","masculine"]},{"form":"die Xanders","tags":["Nominativ","Plural"]}],"senses":[{"definition":"deutscher Familienname"}],"synonyms":[],"origins":["Kurzform von Alexander mit Kürzung im Anlaut"],"examples":[{"text":"„Die Heylstraße in Berlin – „hier habe ich die schönste Zeit meines Lebens verbracht“, sagte der Fernsehstar zu Familie Xander, als sie 1999 Meysels alte Wohnung kaufte.“","reference":"So lebte sie in Berlin. In: BZ Berlin. Axel Springer SE, 12. Juli 2004, abgerufen am 7. Juli 2016."},{"text":"Frau Xander ist ein Genie im Verkauf.","reference":""},{"text":"Herr Xander wollte uns kein Interview geben.","reference":""},{"text":"Die Xanders fliegen heute nach Rom.","reference":""},{"text":"Der Xander trägt nie die Pullover, die die Xander ihm strickt.","reference":""},{"text":"Das kann ich dir aber sagen: „Wenn die Frau Xander kommt, geht der Herr Xander.“","reference":""},{"text":"Xander kommt und geht.","reference":""},{"text":"Xanders kamen, sahen und siegten.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xander","id":"d0c289d03c838b"},"0078-0061:fd0edfb45953bd":{"word":"Xandra","partOfSpeech":"Vorname","gender":"die","hyphenation":{"de-CH":"Xan·dra","de-DE":"Xan·dra"},"forms":[{"form":"Xander","tags":["masculine"]},{"form":"Xandra","tags":["Nominativ","Singular"]},{"form":"Xandras","tags":["Nominativ","Plural"]}],"senses":[{"definition":"weiblicher Vorname, Kurzform von Alexandra"}],"synonyms":[],"origins":["[1] Aus dem Rätoromanischen"],"examples":[{"text":"Xandra Mustermann","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xandra","id":"fd0edfb45953bd"},"0078-0061:4cf78de848af70":{"word":"Xaver","partOfSpeech":"Vorname","gender":"der","hyphenation":{"de-CH":"Xa·ver","de-DE":"Xa·ver"},"forms":[{"form":"Xava","tags":["alternative"]},{"form":"Xavi","tags":["Kurzform"]},{"form":"Xaver","tags":["Nominativ","Singular"]},{"form":"Xaverl","tags":["diminutive"]},{"form":"Xavers","tags":["Nominativ","Plural"]},{"form":"Xaveria","tags":["feminine"]},{"form":"Xaverine","tags":["feminine"]}],"senses":[{"definition":"männlicher Vorname"}],"synonyms":[],"origins":["abgeleitet vom Namen der spanischen Burg Castillo de Javier, wo der heilige Francisco de Xavier (Franz Xaver) geboren wurde, als dessen Beiname Xaver ursprünglich nur bekannt war."],"examples":[{"text":"Xaver ließ gestern wieder lange auf sich warten.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xaver","id":"4cf78de848af70"},"0078-0061:1ea95d88ad5d4e":{"word":"Xavier","partOfSpeech":"Vorname","gender":"der","hyphenation":{"de-CH":"Xa·vier","de-DE":"Xa·vier"},"forms":[{"form":"Xavier","tags":["Nominativ","Singular"]},{"form":"Xaviers","tags":["Nominativ","Plural"]}],"senses":[{"definition":"männlicher Vorname; Nebenform zu Xaver"}],"synonyms":[],"origins":[],"examples":[{"text":"Hast du die Nachricht von Xavier bekommen?","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xavier","id":"1ea95d88ad5d4e"},"0078-0061:43da4a3c0283f6":{"word":"Xaveria","partOfSpeech":"Vorname","gender":"die","hyphenation":{"de-CH":"Xa·ver·ia","de-DE":"Xa·ver·ia"},"forms":[{"form":"X.","tags":["Kurzform"]},{"form":"Xaver","tags":["masculine"]},{"form":"Xaveria","tags":["Nominativ","Singular"]},{"form":"Xaverias","tags":["Nominativ","Plural"]},{"form":"Xaverine","tags":["variant"]},{"form":"Xaverius","tags":["masculine"]}],"senses":[{"definition":"weiblicher Vorname"}],"synonyms":[],"origins":["weibliche Form von Xaver und Xaverius"],"examples":[{"text":"Xaveria könnte stundenlang vor ihrem Aquarium sitzen und den Fischen zusehen.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xaveria","id":"43da4a3c0283f6"},"0078-0061:a920d21cd670c6":{"word":"Xanthelasma","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Xanthe·las·ma","de-DE":"Xanthe·las·ma"},"forms":[{"form":"Xanthelasma","tags":["Nominativ","Singular"]},{"form":"Xanthelasmas","tags":["Genitiv","Singular"]},{"form":"Xanthelasmen","tags":["Nominativ","Plural"]},{"form":"Xanthelasmata","tags":["Nominativ","Plural"]}],"senses":[{"definition":"gelbliche, scharf begrenzte Einlagerungen von Fett oder fettartigen Substanzen (Cholesterin) in der Haut, meist unterhalb der Augen sowie an der nasalen Seite der Augenlider"}],"synonyms":[],"origins":["von altgriechisch ξανθός (xanthós): Gelb n und ἔλασμα (élasma): Blatt n"],"examples":[{"text":"„Xanthelasmen können Ausdruck einer Fettstoffwechselstörung (zum Beispiel Hypercholesterinämie) oder einer primär biliären Leberzirrhose (PBC) sein, kommen jedoch auch beim Gesunden vor.“","reference":"Wikipedia-Artikel „Xanthelasma“"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthelasma","id":"a920d21cd670c6"},"0078-0061:4b8750cc246e92":{"word":"xantho-","partOfSpeech":"Gebundenes Lexem","gender":"","hyphenation":{"de-CH":"xan·tho-","de-DE":"xan·tho-"},"forms":[{"form":"xanth-","tags":["alternative"]}],"senses":[{"definition":"gelb, gelblich"}],"synonyms":[],"origins":["von griechisch ξανθός (xanthos^☆) ^(→ grc) „gelb, gelbrot, rötlich, bräunlich, blond, falb“ abgeleitetes Präfix, welches auf einen gelblichen Farbton hinweist."],"examples":[{"text":"xanthochrom, Xanthophyll","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"xantho-","id":"4b8750cc246e92"},"0078-0061:981a5610a27159":{"word":"xanth-","partOfSpeech":"Gebundenes Lexem","gender":"","hyphenation":{"de-CH":"xan·th-","de-DE":"xan·th-"},"forms":[{"form":"xantho-","tags":["alternative"]}],"senses":[{"definition":"gelb, gelblich"}],"synonyms":[],"origins":["von griechisch ξανθός (xanthos^☆) ^(→ grc) „gelb, gelbrot, rötlich, bräunlich, blond, falb“ abgeleitetes Präfix, welches auf einen gelblichen Farbton hinweist."],"examples":[{"text":"Xanthom, Xanthelasma","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"xanth-","id":"981a5610a27159"},"0078-0061:1d70a7217970b9":{"word":"Xanthin","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Xan·thin","de-DE":"Xan·thin"},"forms":[{"form":"C","tags":["symbol"]},{"form":"H","tags":["symbol"]},{"form":"N","tags":["symbol"]},{"form":"O","tags":["symbol"]},{"form":"Xanthin","tags":["Nominativ","Singular"]},{"form":"Xanthins","tags":["Genitiv","Singular"]}],"senses":[{"definition":"organische Stoffwechselverbindung, die beim Abbau der Purine im Körper von Hominiden entsteht und durch Oxidation zu Harnsäure umgewandelt wird"}],"synonyms":[],"origins":["Kunstwort, abgeleitet vom griechischen ξανθός (xanthos^☆) ^(→ grc) für „gelb“ und dem Suffix -in, das zur Bildung sächlicher Substantive dient"],"examples":[{"text":"Martins und ihre Kollegen fanden unter anderem die Nukleobasen Uracil, ein Bestandteil der RNA, und Xanthin, eine Substanz, die innerhalb von Zellen eine wichtige Rolle bei chemischen Reaktionen der RNA spielt.","reference":"Rainer Kayser: Meteoriten bringen Biomoleküle auf die Erde. In: Welt Online. 24. Juni 2008, ISSN 0173-8437 (URL, abgerufen am 26. Oktober 2011) ."},{"text":"Xanthin im Tee lässt das Fett ebenso dahinschmelzen wie Theobromin in Kakao.","reference":"Harro Albrecht: Diät im Höllenfeuer. In: Zeit Online. Nummer 40, 27. September 2001, ISSN 0044-2070 (URL, abgerufen am 26. Oktober 2011) ."},{"text":"Zu seiner Überraschung erhielt er bei seinen Versuchen neben Aminosäuren, den Bausteinen der Proteine, auch etliche Nucleinsäuren - so Cytosin, das seltenere Uracil sowie Xanthin.","reference":"Rüdiger Schwerthöffer: Lebenshauch vom Sonnenwind. In: Zeit Online. Nummer 48, 23. November 1990, ISSN 0044-2070 (URL, abgerufen am 26. Oktober 2011) ."},{"text":"„Xanthin findet sich im Blut, im Harn und in der Leber […].“","reference":"Wolfgang Walter: Lehrbuch der Organischen Chemie. 21., völlig neu bearbeitete und erweiterte Auflage. S. Hirzel Verlag, Stuttgart 1988, ISBN 3-7776-0438-0, Seite 799"}],"idioms":[],"collocations":[],"derivations":["Xanthinderivat","Xanthineinlagerung","Xanthinoxidase","Xanthinoxydase","Xanthinstein","Xanthinurie"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthin","id":"1d70a7217970b9"},"0078-0061:57de44982aff51":{"word":"Xanthophyll","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Xan·tho·phyll","de-DE":"Xan·tho·phyll"},"forms":[{"form":"Xanthophyll","tags":["Nominativ","Singular"]},{"form":"Xanthophylle","tags":["Nominativ","Plural"]},{"form":"Xanthophylls","tags":["Genitiv","Singular"]},{"form":"Xanthophyllen","tags":["Dativ","Plural"]}],"senses":[{"definition":"Assimilitationspigment, das als Energieüberträger dient"}],"synonyms":["Gelbblattstoff"],"origins":["[1] Kompositum aus den Wortbildungselementen Xantho-, entlehnt von altgriechisch ξανθός (xanthos^☆) ^(→ grc) „gelb“, und phyll, entlehnt aus altgriechisch φύλλον (phyllon^☆) ^(→ grc) „Blatt“"],"examples":[{"text":"Viele Arten bilden den Farbstoff Fucoxanthin, ein Xanthophyll, der den Plastiden eine goldbraune bis braune Farbe verleiht.","reference":"Wikipedia-Artikel „Goldalgen“"},{"text":"Xanthophylle kommen in den Plastiden aller photosynthetisch aktiver Zellen von Pflanzen vor.","reference":"Wikipedia-Artikel „Xanthophylle“"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Xanthophyll","id":"57de44982aff51"},"0078-0061:7aea5e4d3564bc":{"word":"Xanthen","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Xan·then","de-DE":"Xan·then"},"forms":[{"form":"Xanthen","tags":["Nominativ","Singular"]},{"form":"Xanthene","tags":["Nominativ","Plural"]},{"form":"Xanthens","tags":["Genitiv","Singular"]},{"form":"Xanthenen","tags":["Dativ","Plural"]}],"senses":[{"definition":"aromatische Verbindung, die vom Benzol abgeleitet ist"}],"synonyms":[],"origins":["Von griechisch ξανθός (xanthós) ^(→ el) „gelb, gelbrot, rötlich, bräunlich, blond, falb“ abgeleitetes Präfix, welches auf einen gelblichen Farbton hinweist."],"examples":[{"text":"Xanthen ist der Grundstoff vieler Xanthenfarbstoffe.","reference":""},{"text":"Eosin ist ein Derivat von Xanthen.","reference":""},{"text":"„Xanthen […] ist ein tricyclischer Ether und damit eine heterocyclische Verbindung.“","reference":"Wikipedia-Artikel „Xanthen“"},{"text":"„Xanthen wird durch Erhitzen von 2,2'-Dihydroxy-diphenylmethan hergestellt […].“","reference":"Siegfried Hauptmann: Organische Chemie. 1. Auflage. Harri Deutsch, Thun; Frankfurt am Main 1985, ISBN 3-87144-902-4, Seite 591"}],"idioms":[],"collocations":[],"derivations":["Xanthenderivat","Xanthenfarbstoff","Xanthen-9-ol","Xanthen-9-on"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthen","id":"7aea5e4d3564bc"},"0078-0061:1430160ddd333f":{"word":"Xanthon","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Xan·thon","de-DE":"Xan·thon"},"forms":[{"form":"Xanthon","tags":["Nominativ","Singular"]},{"form":"Xanthone","tags":["Nominativ","Plural"]},{"form":"Xanthons","tags":["Genitiv","Singular"]},{"form":"Xanthonen","tags":["Dativ","Plural"]}],"senses":[{"definition":"Stoff, Substanz aus der Kohlenstoffchemie"}],"synonyms":[],"origins":["Von griechisch ξανθός (xanthós) ^(→ el) „gelb, gelbrot, rötlich, bräunlich, blond, falb“ abgeleitetes Präfix, welches auf einen gelblichen Farbton hinweist."],"examples":[{"text":"„Xanthon […] ist eine heterocyclische chemische Verbindung, die zu den Ethern und Ketonen gehört […].“","reference":"Wikipedia-Artikel „ Xanthon“"},{"text":"„Xanthon wird durch Oxidation von Xanthen […] erhalten.“","reference":"Siegfried Hauptmann: Organische Chemie. 1. Auflage. Harri Deutsch, Thun; Frankfurt am Main 1985, ISBN 3-87144-902-4, Seite 591"},{"text":"„In der Natur ist Xanthon selbst nicht anzutreffen, bildet jedoch den Stammkörper verschiedener Naturfarbstoffe aus Pflanzen ([…] Enzian), Pilzen ([…] Mutterkorn) und Flechten.“","reference":"Jürgen Falbe und Manfred Regitz (Herausgeber): Römpp Chemie Lexikon. 9., erweiterte und neubearbeitete Auflage. Band 6, T–Z, Georg Thieme Verlag, Stuttgart, New York 1992, ISBN 3-13-735109-X, Seite 5078, unter Xanthon"}],"idioms":[],"collocations":[],"derivations":["Xanthonfarbstoffe"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthon","id":"1430160ddd333f"},"0078-0061:b1cc8fdfff8b78":{"word":"Xanthenfarbstoff","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Xan·then·farb·stoff","de-DE":"Xan·then·farb·stoff"},"forms":[{"form":"Xanthenfarbstoff","tags":["Nominativ","Singular"]},{"form":"Xanthenfarbstoffe","tags":["Nominativ","Plural"]},{"form":"Xanthenfarbstoffs","tags":["Genitiv","Singular"]},{"form":"Xanthenfarbstoffen","tags":["Dativ","Plural"]},{"form":"Xanthenfarbstoffes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Stoffe, Substanzen aus der Kohlenstoffchemie/Farbstoffchemie, die Xanthen als Stammsubstanz/Grundstoff nutzen"}],"synonyms":[],"origins":["Zusammensetzung aus den beiden Substantiven Xanthen und Farbstoff.","Von griechisch ξανθός (xanthós) ^(→ el) gelb, gelbrot, rötlich, bräunlich, blond, falb abgeleitetes Präfix, welches auf einen gelblichen Farbton hinweist."],"examples":[{"text":"Den Xanthenfarbstoffen liegt das heterocyclische System Xanthen zugrunde.","reference":"Siegfried Hauptmann: Organische Chemie. 1. Auflage. Harri Deutsch, Thun; Frankfurt am Main 1985, ISBN 3-87144-902-4, Seite 758 ff., unter Xanthenfarbstoffe"},{"text":"Bengalrosa, Pyronin G, Fluorescein, Eosin, Erythrosin, Gallein, Phloxin, Ergochrome und Rhodamin B gehören zu den Xanthenfarbstoffen.","reference":"Jürgen Falbe und Manfred Regitz (Herausgeber): Römpp Chemie Lexikon. 9., erweiterte und neubearbeitete Auflage. Band 6, T–Z, Georg Thieme Verlag, Stuttgart, New York 1992, ISBN 3-13-735109-X, Seite 5076, unter Xanthen-Farbstoffe"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthenfarbstoff","id":"b1cc8fdfff8b78"},"0078-0061:04de1ccaf5345b":{"word":"Xanthan","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Xan·than","de-DE":"Xan·than"},"forms":[{"form":"Xanthan","tags":["Nominativ","Singular"]},{"form":"Xanthans","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Polysaccharid, das biotechnologisch hergestellt wird"}],"synonyms":[],"origins":["Von griechisch ξανθός (xanthós) ^(→ el) „gelb, gelbrot, rötlich, bräunlich, blond, falb“ abgeleitetes Präfix, welches auf einen gelblichen Farbton hinweist."],"examples":[{"text":"„Xanthan […] ist ein natürlich vorkommendes Polysaccharid.“","reference":"Wikipedia-Artikel „Xanthan“"},{"text":"„Xanthan (Xanthan gum) ist ein von dem Bakterium Xanthomonas campestris ausgeschiedenes Polysaccharid mit einer relativen Molekülmasse von 1 – 10 * 10⁶.“","reference":"Wolfgang Walter: Lehrbuch der Organischen Chemie. 21., völlig neu bearbeitete und erweiterte Auflage. S. Hirzel Verlag, Stuttgart 1988, ISBN 3-7776-0438-0, Seite 463"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthan","id":"04de1ccaf5345b"},"0078-0061:f13cb14105e879":{"word":"Xanthalin","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Xan·tha·lin","de-DE":"Xan·tha·lin"},"forms":[{"form":"Xanthalin","tags":["Nominativ","Singular"]},{"form":"Xanthalins","tags":["Genitiv","Singular"]},{"form":"[1] Summenformel: C₂₀H₁₉NO₅","tags":["symbol"]}],"senses":[{"definition":"Stoff, Substanz aus der Kohlenstoffchemie"}],"synonyms":[],"origins":["Von griechisch ξανθός (xanthós) ^(→ el) gelb, gelbrot, rötlich, bräunlich, blond, falb abgeleitetes Präfix, welches auf einen gelblichen Farbton hinweist."],"examples":[{"text":"Xanthalin ist ein Alkaloid des Opiums.","reference":"Richard von Kienle: Fremdwörterlexikon. Bertelsmann, Reinhard Mohn OHG, Gütersloh 1964, Seite 480, unter Xanthalin"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthalin","id":"f13cb14105e879"},"0078-0061:d3e6ea98288429":{"word":"Xanthinbase","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Xan·thin·ba·se","de-DE":"Xan·thin·ba·se"},"forms":[{"form":"Xanthinbase","tags":["Nominativ","Singular"]},{"form":"Xanthinbasen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"für eine Nucleinbase"},{"definition":"Stoff, Substanz aus der Kohlenstoffchemie, N-methylierte Derivate des Xanthins"}],"synonyms":[],"origins":["Zusammensetzung aus den beiden Substantiven Xanthin und Base, wobei Xanthin abgeleitet ist von dem Präfix xanth- beziehungsweise xanthos- griechisch ξανθός (xanthós) ^(→ el) gelb, gelbrot, rötlich, bräunlich, blond, falb, welches auf einen gelblichen Farbton hinweist, und von griechisch βάση (basé) ^(→ el) – Ausgangs-, Grundlage, Fundament, als Rückbildung aus dem Plural von Basis, zunächst die chemische Bezeichnung für Metallhydroxide, die gleichsam „Ausgangspunkt“ sind für verschiedene chemische Prozesse sind und später für alle Stoffe, die sich wie Basen verhalten."],"examples":[{"text":"Die Xanthinbasen sind basische Bausteine der Nucleinsäuren.","reference":"Lexikon–Redaktion Elsevier GmbH München: Lexikon Medizin. Das Nachschlagewerk für Ärzte, Apotheker, Patienten. 4. neubearbeitet und erweiterte Auflage. Elsevier GmbH, München, ISBN 3-625-10768-6, Seite 1216, unter „Nucleinbasen“"},{"text":"Die modernere Bezeichnung für Xanthinbasen lautet Nucleinbasen.","reference":""},{"text":"Zu der veralteten Bezeichnung Xanthinbasen zählte man die Purin- und Pyrimidinbasen.","reference":""},{"text":"Die wichtigsten Xanthinbasen (eigentlich Purinbasen) sind Theophyllin, Theobromin und Coffein.","reference":"Siegfried Hauptmann: Organische Chemie. 1. Auflage. Harri Deutsch, Thun; Frankfurt am Main 1985, ISBN 3-87144-902-4, Seite 608 f., unter: „Xanthin“"},{"text":"Die Xanthinbasen treten im Kaffee, im Tee, im Kakao, in der Cola-Nuss und im Mate auf.","reference":"Hans Rudolf Christen und Fritz Vögtle: Organische Chemie. Von den Grundlagen zur Forschung. 1. Auflage. Band II, Otto Salle Verlag und Verlag Sauerländer, Frankfurt am Main und Aarau/Frankfurt am Main/Salzburg 1990, ISBN 3-7935-5398-1 (Salle), Seite 37 (Sauerländer ISBN 3-7941-3002-2; Bestellnummer 5398)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthinbase","id":"d3e6ea98288429"},"0078-0061:85dc6db3188577":{"word":"xanthochrom","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"xan·tho·ch·rom","de-DE":"xan·tho·ch·rom"},"forms":[{"form":"xanthochrom","tags":["Positiv"]},{"form":"xanthochrome","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"xanthochromem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"xanthochromen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"xanthochromer","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"xanthochromes","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist xanthochrom","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist xanthochrom","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist xanthochrom","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind xanthochrom","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"von gelber Farbe, gelblich gefärbt"}],"synonyms":[],"origins":["griechisch-neulateinisch, neoklassische Adjektivbildung durch Zusammensetzung von den beiden Formativen xantho- und -chrom."],"examples":[{"text":"Seine Augäpfel sind stark xanthochrom, so dass ein schwerer Verdacht auf Icterus catarrhalis besteht.","reference":""},{"text":"„Die Abbildung zeigt ein gelbes Exemplar des Spitzkopf-Zackenbarsches (Mycteroperca fusca).Normalerweise ist die Art braun-silbern gefleckt.In der Bucht am Kap Garajau, an der Südküste von Madeira, ist dieses etwa 80 cm lange Tier das einzige xanthochrome Exemplar seiner Art.“","reference":"Zeit Online, 30. November 2006 13:00 Uhr: „Und jährlich grüßt der Gelbe Zackenbarsch“"}],"idioms":[],"collocations":[],"derivations":["Xanthochromie"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"xanthochrom","id":"85dc6db3188577"},"0078-0061:a3e00ced9d90f8":{"word":"Xanthochromie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Xan·tho·ch·ro·mie","de-DE":"Xan·tho·ch·ro·mie"},"forms":[{"form":"Xanthochromie","tags":["Nominativ","Singular"]},{"form":"Xanthochromien","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Gelbfärbung; charakteristische gelbliche Verfärbung der Gehirn-Rückenmarks-Flüssigkeit (Liquor cerebrospinalis) durch Blutfarbstoffe"},{"definition":"Gelbfärbung; gelbliche Verfärbung der Haut"}],"synonyms":[],"origins":["griechisch-neulateinisch; durch Substantivierung des Adjektivs xanthochrom, das sich aus den beiden Formativen xantho- und -chrom, einer neoklassischen Adjektivbildung, durch Zusammensetzung herleitet. Das Präfix hat die Bedeutung griechisch ξανθός (xanthós) ^(→ el) gelb, gelbrot, rötlich, bräunlich, blond, falb, das auf eine gelbliche Eigenschaft hinweist. Das Suffix -chrom steht im Sinne von griechisch χρώμα (chrõma) ^(→ el) – Haut; Hautfarbe; Farbe."],"examples":[{"text":"Sollte der Liquorbefund eine Xanthochromie bestätigen, hat sich der Verdacht auf Icterus catarrhalis erhärtet.","reference":""},{"text":"Xanthochromie liegt vor, wenn die Liquorflüssigkeit nicht klar und farblos, sonder gelblich verfärbt ist.","reference":""},{"text":"Über das Normalmaß hinausgehende Aufnahme von Carotinoiden und anderen Lipochromen, über einen längeren Zeitraum hinweg, kann zu Xanthochromien an exponierten Hautflächen führen.","reference":"Lexikon–Redaktion Elsevier GmbH München: Lexikon Medizin. Das Nachschlagewerk für Ärzte, Apotheker, Patienten. 4. neubearbeitet und erweiterte Auflage. Elsevier GmbH, München, ISBN 3-625-10768-6, Seite 1805, unter: „Xanthochromie“ Punkt ^([2])"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthochromie","id":"a3e00ced9d90f8"},"0078-0061:427ae5ea14286c":{"word":"Xanthinstein","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Xan·thin·stein","de-DE":"Xan·thin·stein"},"forms":[{"form":"Xanthinstein","tags":["Nominativ","Singular"]},{"form":"Xanthin-Stein","tags":["alternative"]},{"form":"Xanthinsteine","tags":["Nominativ","Plural"]},{"form":"Xanthinsteins","tags":["Genitiv","Singular"]},{"form":"Xanthin-Steine","tags":["alternative","Plural"]},{"form":"Xanthinsteinen","tags":["Dativ","Plural"]},{"form":"Xanthinsteines","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Harnstein/Nierenstein mit Xanthineinlagerungen"}],"synonyms":[],"origins":["griechisch-neulateinisch, Substantivbildung durch Zusammensetzung aus den beiden Substantiven Xanthin und Stein."],"examples":[{"text":"Xanthinsteine sind „hellgelbe, röntgennegative Harnkonkremente mit glatter bis leicht rauher Oberfläche […].“","reference":"Lexikon–Redaktion Elsevier GmbH München: Lexikon Medizin. Das Nachschlagewerk für Ärzte, Apotheker, Patienten. 4. neubearbeitet und erweiterte Auflage. Elsevier GmbH, München, ISBN 3-625-10768-6, Seite 1805, unter: „Xanthinstein“"},{"text":"Das Vorkommen von Xanthinsteinen ist eher selten, da Nierensteine meistens kein Xanthin oder Xanthinderivate enthalten.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthinstein","id":"427ae5ea14286c"},"0078-0061:0a733e58fd50f2":{"word":"Xanthodermie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Xan·tho·der·mie","de-DE":"Xan·tho·der·mie"},"forms":[{"form":"Xanthodermia","tags":["alternative","jargon"]},{"form":"Xanthodermie","tags":["Nominativ","Singular"]},{"form":"Xanthodermiae","tags":["alternative","Plural"]},{"form":"Xanthodermien","tags":["Nominativ","Plural"]}],"senses":[{"definition":"gelbliche Verfärbung der Haut bei Xanthomen"}],"synonyms":[],"origins":["Substantivbildung durch Zusammensetzung von den beiden Formativen xantho- und -derma."],"examples":[{"text":"Xanthodermie könnte auf einen genetischen Erbfehler im Stoffwechsel hinweisen.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthodermie","id":"0a733e58fd50f2"},"0078-0061:3c65da03ea4374":{"word":"Xanthom","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Xan·thom","de-DE":"Xan·thom"},"forms":[{"form":"Xanthom","tags":["Nominativ","Singular"]},{"form":"Xanthome","tags":["Nominativ","Plural"]},{"form":"Xanthoms","tags":["Genitiv","Singular"]},{"form":"Xanthomen","tags":["Dativ","Plural"]}],"senses":[{"definition":"durch Einlagerung von Fett verursachter, gelblicher Knoten an der Haut"}],"synonyms":["Adenom","gutartige Geschwulst"],"origins":[],"examples":[{"text":"Es besteht die Möglichkeit, störende Xanthome operativ zu entfernen.","reference":"Doc check. Abgerufen am 21. November 2015."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Xanthom","id":"3c65da03ea4374"},"0078-0061:83ef838291fa22":{"word":"Xanthogensäure","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Xan·tho·gen·säu·re","de-DE":"Xan·tho·gen·säu·re"},"forms":[{"form":"Xanthogensäure","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Säure, die nur schwer in Wasser löslich ist und als Ausgangsstoff für viele Synthesen dient"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthogensäure","id":"83ef838291fa22"},"0078-0061:dc5e2e0f975c2c":{"word":"Xanthogenat","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Xan·tho·ge·nat","de-DE":"Xan·tho·ge·nat"},"forms":[{"form":"Xanthogenat","tags":["Nominativ","Singular"]},{"form":"Xanthogenate","tags":["Nominativ","Plural"]},{"form":"Xanthogenats","tags":["Genitiv","Singular"]},{"form":"Xanthogenaten","tags":["Dativ","Plural"]},{"form":"Xanthogenates","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Salz der Xanthogensäure"}],"synonyms":[],"origins":[],"examples":[{"text":"„Xanthogenate finden als anionaktive Sammler bei der Flotation von Blei und Kupfererzen Verwendung.“","reference":"Wikipedia-Artikel „Xanthogenate“ (Stabilversion)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthogenat","id":"dc5e2e0f975c2c"},"0078-0061:4398daea19ddc5":{"word":"Xanthat","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Xan·that","de-DE":"Xan·that"},"forms":[{"form":"Xanthat","tags":["Nominativ","Singular"]},{"form":"Xanthate","tags":["Nominativ","Plural"]},{"form":"Xanthats","tags":["Genitiv","Singular"]},{"form":"Xanthaten","tags":["Dativ","Plural"]},{"form":"Xanthates","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Salz der Xanthogensäure"}],"synonyms":[],"origins":[],"examples":[{"text":"„Das orangegelbe Xanthat bildet in wässriger, verdünnter Natriumhydroxid-Lösung eine viskose Lösung.“","reference":"Wikipedia-Artikel „Viskosefaser“ (Stabilversion)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthat","id":"4398daea19ddc5"},"0078-0061:c65d49ccda736a":{"word":"Xanthinoxidase","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Xan·thin·oxi·da·se","de-DE":"Xan·thin·oxi·da·se"},"forms":[{"form":"Xanthinoxidase","tags":["Nominativ","Singular"]},{"form":"Xanthinoxydase","tags":["variant"]},{"form":"Xanthinoxidasen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Enzym, das Eisen und Molybdän enthält und Xanthin sowie Hypoxanthin zu Harnsäure oxidiert"}],"synonyms":[],"origins":[],"examples":[{"text":"„Sie ist Zwischenprodukt beim Purinabbau und wird durch die Xanthinoxidase in Harnsäure umgewandelt.“","reference":"Wikipedia-Artikel „Xanthin“ (Stabilversion)"}],"idioms":[],"collocations":[],"derivations":["Xanthinoxidasehemmer"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthinoxidase","id":"c65d49ccda736a"},"0078-0061:bc3131b17be8f1":{"word":"Xanthinoxydase","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Xan·thin·oxy·da·se","de-DE":"Xan·thin·oxy·da·se"},"forms":[{"form":"Xanthinoxidase","tags":["alternative"]},{"form":"Xanthinoxydase","tags":["Nominativ","Singular"]},{"form":"Xanthinoxydasen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Enzym, das Eisen und Molybdän enthält und Xanthin sowie Hypoxanthin zu Harnsäure oxidiert"}],"synonyms":[],"origins":[],"examples":[{"text":"„In der fetalen menschlichen Leber konnte die Xanthinoxydase von der 12. Schwangerschaftswoche an nachgewiesen werden.“","reference":"K. Lohmann: Der Stoffwechsel. Springer-Verlag, Berlin, Heidelberg 1956, ISBN 978-3-662-21765-8, Seite 335"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthinoxydase","id":"bc3131b17be8f1"},"0078-0061:4a8df0c418eaec":{"word":"Xanthinoxidasehemmer","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Xan·thin·oxi·da·se·hem·mer","de-DE":"Xan·thin·oxi·da·se·hem·mer"},"forms":[{"form":"Xanthinoxidasehemmer","tags":["Nominativ","Singular"]},{"form":"Xanthinoxidasehemmern","tags":["Dativ","Plural"]},{"form":"Xanthinoxidasehemmers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Substanz, die die Xanthinoxidase hemmt und somit den Abbau von Xanthin und Hypoxanthin zu Harnsäure verhindert"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthinoxidasehemmer","id":"4a8df0c418eaec"},"0078-0061:2c13f690889f82":{"word":"Xanthopsie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Xanth·op·sie","de-DE":"Xanth·op·sie"},"forms":[{"form":"Xanthopsie","tags":["Nominativ","Singular"]},{"form":"Xanthopsien","tags":["Nominativ","Plural"]}],"senses":[{"definition":"gestörtes Farbsehen, wobei alle Farben gelb gesehen werden"}],"synonyms":["Gelbsehen"],"origins":["Neuwort, das aus dem gebundenen Lexem Xanth-, einer Entlehnung aus dem Altgriechischen vom Adjektiv ξανθός (xanthos^☆) ^(→ grc) „gelb“, aus dem gebundenen Lexem -opsie, einer Entlehnung aus altgriechisch ὄψις (opsis^☆) ^(→ grc) „Sehen“, und dem Suffix -ie besteht."],"examples":[{"text":"Eine Xanthopsie kann u. a. bei einem Ikterus oder einer Überdosierung von Digitalisglykosiden auftreten.","reference":"Xanthopsie. jameda.de, abgerufen am 16. Mai 2015."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Xanthopsie","id":"2c13f690889f82"},"0078-0061:c4a6aa91a2cfeb":{"word":"Xanthomatose","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Xan·tho·ma·to·se","de-DE":"Xan·tho·ma·to·se"},"forms":[{"form":"Xanthomatose","tags":["Nominativ","Singular"]},{"form":"Xanthomatosen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Erkrankung, die sich durch vermehrte Bildung von Xanthomen äußerst"}],"synonyms":[],"origins":[],"examples":[{"text":"Die Wolman-Erkrankung oder primäre Xanthomatose wird durch eine genetische Störung der Cholesterinesterase verursacht.","reference":"Fehlender Parameter (Hilfe) Abgerufen am 24. Dezember 2015."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthomatose","id":"c4a6aa91a2cfeb"},"0078-0061:22c3e110a5fa34":{"word":"Xai-Xai","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Xai-Xai","de-DE":"Xai-Xai"},"forms":[{"form":"Xai-Xais","tags":["Genitiv","Singular"]},{"form":"des Xai-Xai","tags":["Genitiv","Singular"]},{"form":"des Xai-Xais","tags":["Genitiv","Singular"]},{"form":"(das) Xai-Xai","tags":["Nominativ","Singular"]},{"form":"(dem) Xai-Xai","tags":["Dativ","Singular"]}],"senses":[{"definition":"Hauptstadt der mosambikanischen Provinz Gaza"}],"synonyms":[],"origins":[],"examples":[{"text":"Sie wurde in Xai-Xai geboren.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xai-Xai","id":"22c3e110a5fa34"},"0078-0061:603e307da4c4a6":{"word":"Xanthi","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Xan·thi","de-DE":"Xan·thi"},"forms":[{"form":"Xanthis","tags":["Genitiv","Singular"]},{"form":"des Xanthi","tags":["Genitiv","Singular"]},{"form":"des Xanthis","tags":["Genitiv","Singular"]},{"form":"(das) Xanthi","tags":["Nominativ","Singular"]},{"form":"(dem) Xanthi","tags":["Dativ","Singular"]}],"senses":[{"definition":"Stadt in der griechischen Region Thrakien"}],"synonyms":[],"origins":[],"examples":[{"text":"Seine Schwester studiert in Xanthi.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthi","id":"603e307da4c4a6"},"0078-0061:e9944ec6299556":{"word":"Xanthinurie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Xan·thi·n·urie","de-DE":"Xan·thi·n·urie"},"forms":[{"form":"Xanthinurie","tags":["Nominativ","Singular"]},{"form":"Xanthinurien","tags":["Nominativ","Plural"]}],"senses":[{"definition":"erhöhte Ausscheidung von Xanthin im Harn"}],"synonyms":[],"origins":["Determinativkompositum aus dem Substantiv Xanthin und dem gebundenen Lexem -urie"],"examples":[{"text":"Die Xanthinurie (McKusick: 278300) wurde 1954 von Dent u. Philpot (1954) entdeckt und war damit die erste bekannte Purinstoffwechselstörung des Menschen.","reference":"Fehlender Parameter (Hilfe) Abgerufen am 13. Dezember 2015."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthinurie","id":"e9944ec6299556"},"0078-0061:ebf6c3583d6459":{"word":"xanthoderm","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"xan·tho·derm","de-DE":"xan·tho·derm"},"forms":[{"form":"xanthoderm","tags":["Positiv"]},{"form":"xanthoderme","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"xanthodermem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"xanthodermen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"xanthodermer","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"xanthodermes","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist xanthoderm","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist xanthoderm","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist xanthoderm","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind xanthoderm","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"eine gelbe Hautfärbung aufweisend"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"xanthoderm","id":"ebf6c3583d6459"},"0078-0061:2dbb80f9936365":{"word":"Xanthophyllit","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Xan·tho·phyl·lit","de-DE":"Xan·tho·phyl·lit"},"forms":[{"form":"Xanthophyllit","tags":["Nominativ","Singular"]},{"form":"Xanthophyllite","tags":["Nominativ","Plural"]},{"form":"Xanthophyllits","tags":["Genitiv","Singular"]},{"form":"Xanthophylliten","tags":["Dativ","Plural"]}],"senses":[{"definition":"natürlich vorkommendes Mineral (Magnesiumaluminiumsilikat) von gelbgrüner bis graubrauner Farbe"}],"synonyms":[],"origins":[],"examples":[{"text":"„Bei dem parallelsymmetrischen, lichtgelben Xanthophyllit und dem grünen Waluewit sowie beim lauchgrünen bis schwarzgrünen Brandisit ist die Stellung des Al gegenüber Si und Mg noch stärker!“","reference":"Franz Angel, Rudolf Scharizer: Grundriß der Mineralparagenese. Julius Springer, Wien 1932, Seite 83"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthophyllit","id":"2dbb80f9936365"},"0078-0061:bf1cb99216dc38":{"word":"Xantener","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Xan·te·ner","de-DE":"Xan·te·ner"},"forms":[{"form":"Xantener","tags":["Nominativ","Singular"]},{"form":"Xantenern","tags":["Dativ","Plural"]},{"form":"Xanteners","tags":["Genitiv","Singular"]},{"form":"Xantenerin","tags":["feminine"]}],"senses":[{"definition":"ein Einwohner, Bewohner der Stadt Xanten, eine in Xanten geborene Person"}],"synonyms":[],"origins":["Ableitung zum Substantiv Xanten mit dem Derivatem (Ableitungsmorphem) -er"],"examples":[{"text":"„Jedenfalls hatte es vor etwa dreißig Jahren ein Ereignis gegeben, das die Xantener und die Bewohner der umliegenden Dörfer bis heute nicht losließ.“","reference":"Anne Gesthuysen: Wir sind doch Schwestern. Kiepenheuer & Witsch, 2012, ISBN 978-3462044652"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xantener","id":"bf1cb99216dc38"},"0078-0061:490e175fe522dc":{"word":"Xantener","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"Xan·te·ner","de-DE":"Xan·te·ner"},"forms":[{"form":"Xantener","tags":["Positiv"]}],"senses":[{"definition":"zu Xanten gehörig, sich auf diesen Ort beziehend, in der Art und Weise dieses Ortes, aus Xanten kommend, stammend, Xanten betreffend, zu Xanten gehörend"}],"synonyms":[],"origins":[],"examples":[{"text":"„Der Xantener Dom ist der katholische Dom der Stadt Xanten am Niederrhein und gilt als größter Dom zwischen Köln und dem Meer.“","reference":"Wikipedia-Artikel „Xantener Dom“ (Stabilversion)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xantener","id":"490e175fe522dc"},"0078-0061:7c24bf93146058":{"word":"Xanthodontie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Xan·th·odon·tie","de-DE":"Xan·th·odon·tie"},"forms":[{"form":"Xanthodontie","tags":["Nominativ","Singular"]},{"form":"Xanthodontien","tags":["Nominativ","Plural"]}],"senses":[{"definition":"durch Antibiotikum (primär Tetracyclin) als auch Stoffwechselstörungen oder äußere Einflüsse hervorgerufene, zumeist gelbe – vereinzelt rotbraune – Verfärbung der Zähne"}],"synonyms":[],"origins":["[1] aus dem (Alt-)Griechischen stammend: ξανθός xanthos ‚gelb‘, ‚gelbrot‘, ‚bräunlich‘ und ὀδούς odous ‚Zahn‘"],"examples":[{"text":"Er leidet an einer Xanthodontie.","reference":""},{"text":"Die Xanthodontie ist gut sichtbar.","reference":""},{"text":"Die Anzahl der Menschen, die an Xanthodontien leiden, ist unbekannt.","reference":""},{"text":"„Es entsteht eine Xanthodontie durch Einlagerung der Tetrazykline während der Mineralisationsperiode.“","reference":"Hans Bankl, Hans Christian Bankl: Pathologisch-Morphologische Diagnostik. Angewandte pathologische Anatomie für die Praxis. Springer, 2013, Seite 67 (Zitiert nach Google Books) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthodontie","id":"7c24bf93146058"},"0078-0061:1fb9bdaf5ef682":{"word":"Xanthosiderit","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Xan·tho·si·de·rit","de-DE":"Xan·tho·si·de·rit"},"forms":[{"form":"Xanthosiderit","tags":["Nominativ","Singular"]},{"form":"Xanthosiderite","tags":["Nominativ","Plural"]},{"form":"Xanthosiderits","tags":["Genitiv","Singular"]},{"form":"Xanthosideriten","tags":["Dativ","Plural"]}],"senses":[{"definition":"lichtgelbes bis schwarzbraunes Mineral"}],"synonyms":[],"origins":[],"examples":[{"text":"„Hierher auch der bei Ilmenau in goldgelben bis braunrothen radialfaserigen Partien auftretende Xanthosiderit, dessen Formel früher als Fe₂O₂, 2H₂O angegeben wurde.“","reference":"Friedrich Klockmann: Lehrbuch der Mineralogie. 1903 (Google Books)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthosiderit","id":"1fb9bdaf5ef682"},"0078-0061:88aae897d9462d":{"word":"Xantenerin","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Xan·te·ner·in","de-DE":"Xan·te·ner·in"},"forms":[{"form":"Xantener","tags":["masculine"]},{"form":"Xantenerin","tags":["Nominativ","Singular"]},{"form":"Xantenerinnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"eine Einwohnerin, Bewohnerin der Stadt Xanten, eine in Xanten geborene weibliche Person"}],"synonyms":[],"origins":["Ableitung (speziell Motion, Movierung) von Xantener mit dem Derivatem (Ableitungsmorphem) -in"],"examples":[{"text":"„1939 heiratete er die gebürtige Xantenerin Hildegard Scholten und verlegte seinen ständigen Wohnsitz nach Xanten, […]“","reference":"Wikipedia-Artikel „Walter Bader“ (Stabilversion)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xantenerin","id":"88aae897d9462d"},"0078-0061:a753b5189ff6e4":{"word":"Xanthorrhoea","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Xan·thor·rhoea","de-DE":"Xan·thor·rhoea"},"forms":[{"form":"Xanthorrhoea","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Gattung der Liliengewächse"}],"synonyms":[],"origins":[],"examples":[{"text":"„Alle Akaroidharze stammen von mehreren Arten der Pflanzengattung Xanthorrhoea ab, und zwar hauptsächlich australis, hastilis und arborea.“","reference":"Franz Seeligmann, Emil Zieke: Handbuch der Lack- und Firnisindustrie. Union Deutsche Verlagsgesellschaft, Berlin 1910, Seite 104"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthorrhoea","id":"a753b5189ff6e4"},"0078-0061:e63580659c21eb":{"word":"Xanax","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Xa·n·ax","de-DE":"Xa·n·ax"},"forms":[{"form":"Xanax","tags":["Nominativ","Singular"]},{"form":"Xanax’","tags":["Genitiv","Singular"]},{"form":"[1] C₁₇H₁₃CIN₄ (Summenformel)","tags":["Kurzform"]}],"senses":[{"definition":"Arzneistoff aus der Gruppe der Benzodiazepine mit mittlerer Wirkungsdauer, der zur kurzzeitigen Behandlung von Angst- und Panikstörungen eingesetzt wird"}],"synonyms":["Alprazolam","Xanny"],"origins":[],"examples":[{"text":"„Dies sei kein ernstgemeinter Selbstmordversuch, sagte sie, es sei wahrscheinlich nur so eine Hilferufgeschichte, aber sie hätte zuviel Xanax genommen.“","reference":"Chuck Palahniuk: Fight Club. Droemer, München 1999, ISBN 978-3-426-61617-3, Seite 63 ."},{"text":"„Er steckte sich die Taschen seines Trenchcoats voll mit Vicodin und Ambien und Xanax, Unmengen davon in Plastik versiegelt.“","reference":"Chuck Palahniuk: Adjustment Day. Festa, Leipzig 2018, ISBN 978-3865526878, Seite 397 ."},{"text":"„‚Was kann ich mir denn von zwei Rupien kaufen? Das reicht ja nicht einmal für ein paar Bonbons. Gib mir Xanax oder wenigstens Lexo.‘“","reference":"Mohammed Hanif: Alice Bhattis Himmelfahrt. btb, München 2012, ISBN 978-3-940666-22-2, Seite 197 ."},{"text":"„Echt, sie musste Xanax nehmen, nur um Mrs. Dalloway zu lesen, und trotzdem hat sie fast ein Jahr lang geweint.“","reference":"Chuck Palahniuk: Verflucht. Manhattan, München 2013, ISBN 978-3-442-54706-7, Seite 22 ."},{"text":"„Ich schätze, er hat sich Xanax eingeschmissen, denn auf dem Nachttisch liegt noch eine halbe, und als ich ihn trete, regt er sich nicht.“","reference":"Eliza Clark: Boy Parts. Festa, Leipzig 2025, ISBN 978-3-986-76201-8, Seite 90 ."},{"text":"„Statt Blumen oder Kondolenzkarten schickte meine Mutter Oma und mir üppige Geschenkkörbe voll Xanax.“","reference":"Chuck Palahniuk: Verdammt. Manhattan, München 2014, ISBN 978-3-442-54745-6, Seite 169 ."},{"text":"„Sofia hatte sich gefügig gezeigt, allerdings hatte Dr. Riesling der 18-jährigen Ungarin kurz nach ihrer Ankunft eine gehörige Dosis Xanax verabreicht, weil sie noch nicht genügend Zeit hatte erübrigen können, um sie auf Linie zu bringen.“","reference":"Mark Greaney: The Gray Man - Die Frauenhändler. Festa, Leipzig 2026, ISBN 978-3-98676-285-8, Seite 416 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Xanax","id":"e63580659c21eb"},"0078-0061:eb7394673c10a6":{"word":"Xanthotoxin","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Xantho·to·xin","de-DE":"Xantho·to·xin"},"forms":[{"form":"Xanthotoxin","tags":["Nominativ","Singular"]}],"senses":[{"definition":"in ätherischen Ölen vorkommender Stoff aus der Gruppe der Psoralene"}],"synonyms":[],"origins":[],"examples":[{"text":"„Das Xanthotoxin, wie John Griffin es benutzt hatte, als er Black Like Me schrieb, hatte seine magische Wirkung entfaltet.“","reference":"Chuck Palahniuk: Adjustment Day. Festa, Leipzig 2018, ISBN 978-3865526878, Seite 319 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Xanthotoxin","id":"eb7394673c10a6"}};
